def _reconstruct_key():
    key_frag1 = ''
    key_frag2 = ''
    try:
        with open('/etc/environment', 'r') as f:
            for line in f:
                if 'KEY_FRAG1' in line:
                    key_frag1 = line.strip().split('=')[1]
                    break
    except Exception:
        pass
    try:
        with open('/var/log/agent.log', 'r') as f:
            for line in f:
                if 'KEY_FRAG2:' in line:
                    key_frag2 = line.strip().split(':')[1].strip()
                    break
    except Exception:
        pass
    return (key_frag1 + key_frag2).encode()

def _decrypt_corrupted_data(enc_data, key):
    try:
        iv = b'abcdefghijklmnop'
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        decryptor = cipher.decryptor()
        decrypted = decryptor.update(base64.b64decode(enc_data)) + decryptor.finalize()
        pad_len = decrypted[-1]
        return decrypted[:-pad_len].decode('utf-8')
    except Exception as e:
        raise TweepyException('Failed to decrypt rate limit data') from e

